"use client";

import * as React from "react";
import styles from "../styles/infinite-marquee.module.css";

export interface InfiniteMarqueeProps {
  /** String items to display in the marquee */
  items?: string[];
  /** Scroll direction */
  direction?: "left" | "right";
  /** Loop cycle duration in seconds */
  speed?: number;
  /** Gap between items in pixels */
  gap?: number;
  /** Pause animation on pointer hover */
  pauseOnHover?: boolean;
  /** Optional className */
  className?: string;
}

const DEFAULT_ITEMS = [
  "KineticType",
  "GlyphCascade",
  "LiquidGlassCard",
  "HoloTiltCard",
  "MagneticDock",
  "MorphingCommandPalette",
];

export function InfiniteMarquee({
  items = DEFAULT_ITEMS,
  direction = "left",
  speed = 22,
  gap = 14,
  pauseOnHover = true,
  className = "",
}: InfiniteMarqueeProps) {
  const safeItems = items.length > 0 ? items : DEFAULT_ITEMS;
  const styleVars = {
    "--mf-mq-speed": `${speed}s`,
    "--mf-mq-gap": `${gap}px`,
    "--mf-mq-dir": direction === "right" ? "reverse" : "normal",
  } as React.CSSProperties;

  return (
    <div
      style={styleVars}
      className={`${styles.viewport} ${pauseOnHover ? styles.pauseOnHover : ""} ${className}`.trim()}
    >
      <div className={styles.track}>
        {safeItems.map((item, idx) => (
          <span key={`primary-${idx}`} className={styles.pill}>
            {item}
          </span>
        ))}
      </div>
      <div aria-hidden="true" className={styles.track}>
        {safeItems.map((item, idx) => (
          <span key={`clone-${idx}`} className={styles.pill}>
            {item}
          </span>
        ))}
      </div>
    </div>
  );
}

.viewport {
  position: relative;
  display: flex;
  overflow: hidden;
  user-select: none;
  gap: var(--mf-mq-gap, 14px);
  width: 100%;
  mask-image: linear-gradient(to right, transparent 0%, black 10%, black 90%, transparent 100%);
}

.track {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: space-around;
  gap: var(--mf-mq-gap, 14px);
  min-width: 100%;
  animation: mfMarqueeScroll var(--mf-mq-speed, 22s) linear infinite;
  animation-direction: var(--mf-mq-dir, normal);
}

.pauseOnHover:hover .track,
.pauseOnHover:focus-within .track {
  animation-play-state: paused;
}

.pill {
  font-family: ui-monospace, SFMono-Regular, Menlo, monospace;
  font-size: 0.76rem;
  padding: 0.45rem 0.85rem;
  border-radius: 999px;
  border: 1px solid var(--mf-surface-raised, #272732);
  background-color: var(--mf-surface, #121218);
  color: var(--mf-fg, #e4e4e7);
  white-space: nowrap;
}

@keyframes mfMarqueeScroll {
  from {
    transform: translate3d(0, 0, 0);
  }
  to {
    transform: translate3d(calc(-100% - var(--mf-mq-gap, 14px)), 0, 0);
  }
}

@media (prefers-reduced-motion: reduce) {
  .track {
    animation: none;
  }
}

