export function NumberTickerTailwind({ value = 12480, suffix = "+" }) {
  const ref = useRef<HTMLSpanElement>(null);
  const inView = useInView(ref, { once: true });
  useEffect(() => {
    if (!inView || !ref.current) return;
    const node = ref.current;
    const c = animate(0, value, {
      duration: 1.6,
      ease: [0.16, 1, 0.3, 1],
      onUpdate: (v) => { node.textContent = Math.round(v).toLocaleString("en-US"); },
    });
    return () => c.stop();
  }, [inView, value]);
  return (
    <span aria-label={value.toLocaleString("en-US") + suffix} className="text-5xl font-semibold tabular-nums tracking-tight text-zinc-100">
      <span ref={ref} aria-hidden>{value.toLocaleString("en-US")}</span>
      <span aria-hidden className="text-zinc-400">{suffix}</span>
    </span>
  );
}

