"use client";

import * as React from "react";
import { animate, motion, useMotionValue, useTransform } from "motion/react";

export function SwipeCardsTailwind({ items = ["Kinetic Type", "Liquid Glass", "Magnetic Dock", "Holo Tilt"] }) {
  const [order, setOrder] = React.useState(() => items.map((_, i) => i));
  const x = useMotionValue(0);
  const rotate = useTransform(x, [-240, 240], [-18, 18]);
  const fly = (dir: number) =>
    animate(x, dir * 420, { duration: 0.28 }).then(() => {
      x.set(0);
      setOrder((o) => [o[o.length - 1], ...o.slice(0, -1)]);
    });
  return (
    <div
      tabIndex={0}
      onKeyDown={(e) => { if (e.key === "ArrowLeft") fly(-1); if (e.key === "ArrowRight") fly(1); }}
      className="relative h-56 w-64 rounded-2xl focus-visible:outline focus-visible:outline-2 focus-visible:outline-offset-[3px] focus-visible:outline-zinc-200"
    >
      {order.map((idx, i) => {
        const depth = order.length - 1 - i;
        const top = depth === 0;
        return (
          <motion.div
            key={idx}
            style={top ? { x, rotate, zIndex: 100 } : { zIndex: 100 - depth }}
            drag={top ? "x" : false}
            onDragEnd={(_, info) => (Math.abs(info.offset.x) > 100 ? fly(Math.sign(info.offset.x)) : animate(x, 0))}
            animate={{ scale: 1 - depth * 0.05, y: depth * 10 }}
            className="absolute inset-0 flex cursor-grab items-center justify-center rounded-2xl border border-zinc-800 bg-zinc-900 text-2xl font-bold text-zinc-100 shadow-xl"
          >
            {items[idx]}
          </motion.div>
        );
      })}
    </div>
  );
}

