"use client";

import * as React from "react";
import styles from "../styles/pulse-loader.module.css";

export interface PulseLoaderProps {
  /** Loader diameter in pixels */
  size?: number;
  /** Duration of one ring expansion in seconds */
  duration?: number;
  /** Number of staggered rings */
  rings?: number;
  /** Ring and core color */
  color?: string;
  /** Accessible label announced by assistive technology */
  label?: string;
  /** Optional className merged onto the root */
  className?: string;
}

export function PulseLoader({
  size = 64,
  duration = 1.8,
  rings = 3,
  color = "#38bdf8",
  label = "Loading",
  className = "",
}: PulseLoaderProps) {
  const total = Math.max(1, Math.round(rings));
  const safeDuration = duration > 0 ? duration : 1.8;
  const styleVars = {
    "--mf-pl-size": `${size}px`,
    "--mf-pl-duration": `${safeDuration}s`,
    "--mf-pl-color": color,
  } as React.CSSProperties;

  return (
    <div role="status" aria-label={label} style={styleVars} className={`${styles.root} ${className}`.trim()}>
      {Array.from({ length: total }, (_, i) => (
        <span
          key={i}
          aria-hidden="true"
          className={styles.ring}
          style={
            {
              animationDelay: `-${((i * safeDuration) / total).toFixed(3)}s`,
              "--mf-pl-static": ((i + 1) / total).toFixed(3),
            } as React.CSSProperties
          }
        />
      ))}
      <span aria-hidden="true" className={styles.core} />
    </div>
  );
}

.root {
  position: relative;
  display: inline-block;
  flex-shrink: 0;
  width: var(--mf-pl-size, 64px);
  height: var(--mf-pl-size, 64px);
}

.ring {
  position: absolute;
  inset: 0;
  border-radius: 50%;
  border: 2px solid var(--mf-pl-color, var(--mf-accent, #38bdf8));
  transform: scale(0);
  opacity: 0;
  animation: mfPulseRing var(--mf-pl-duration, 1.8s) cubic-bezier(0.22, 1, 0.36, 1) infinite;
  will-change: transform, opacity;
}

.core {
  position: absolute;
  inset: 40%;
  border-radius: 50%;
  background-color: var(--mf-pl-color, var(--mf-accent, #38bdf8));
  box-shadow: 0 0 calc(var(--mf-pl-size, 64px) * 0.2) var(--mf-pl-color, var(--mf-accent, #38bdf8));
}

@keyframes mfPulseRing {
  from {
    transform: scale(0);
    opacity: 1;
  }
  to {
    transform: scale(1);
    opacity: 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  .ring {
    animation: none;
    transform: scale(var(--mf-pl-static, 1));
    opacity: calc(1.1 - var(--mf-pl-static, 1));
  }
}

