import { Reorder } from "motion/react";
import { useState } from "react";

export function ReorderListTailwind({ items = ["Design tokens", "Motion primitives", "Component library", "Docs site"] }) {
  const [list, setList] = useState(items);
  const move = (i: number, d: number) => {
    const t = i + d;
    if (t < 0 || t >= list.length) return;
    const next = [...list];
    next.splice(t, 0, next.splice(i, 1)[0]);
    setList(next);
  };
  return (
    <Reorder.Group axis="y" values={list} onReorder={setList} className="w-72 space-y-2">
      {list.map((it, i) => (
        <Reorder.Item
          key={it}
          value={it}
          tabIndex={0}
          onKeyDown={(e) => { if (e.altKey && e.key === "ArrowUp") move(i, -1); if (e.altKey && e.key === "ArrowDown") move(i, 1); }}
          whileDrag={{ scale: 1.04 }}
