@keyframes mfGoFloat {
  0% { transform: translate(-50%, -50%) translate(0, 0) scale(1); }
  50% { transform: translate(-50%, -50%) translate(calc(var(--mf-go-dx, 40px) * 0.6), calc(var(--mf-go-dy, 30px) * -0.4)) scale(1.06); }
  100% { transform: translate(-50%, -50%) translate(var(--mf-go-dx, 40px), var(--mf-go-dy, 30px)) scale(0.96); }
}

