import { useState } from "react";

export function ElasticLettersTailwind({ text = "Feel the spring", radius = 160 }) {
  const [p, setP] = useState<{ x: number; y: number } | null>(null);
  return (
    <h2
      onPointerMove={(e) => setP({ x: e.clientX, y: e.clientY })}
      onPointerLeave={() => setP(null)}
      className="select-none px-10 py-6 text-center text-7xl font-extrabold tracking-tighter text-zinc-100"
    >
      <span className="sr-only">{text}</span>
      {Array.from(text).map((ch, i) => (
        <span
          key={i}
          aria-hidden
          ref={(el) => {
            if (!el) return;
            if (!p) {
              el.style.transform = "none";
              return;
            }
            const r = el.getBoundingClientRect();
            const f = Math.max(0, 1 - Math.hypot(p.x - r.left - r.width / 2, p.y - r.top - r.height / 2) / radius);
            el.style.transform = "translateY(" + -30 * f + "px) scale(" + (1 + 0.15 * f) + "," + (1 + 0.38 * f) + ")";
          }}
          className="inline-block origin-bottom transition-transform duration-500 ease-[cubic-bezier(0.34,1.56,0.64,1)]"
        >
          {ch === " " ? "\u00a0" : ch}
        </span>
      ))}
    </h2>
  );
}

