"use client";

import { useEffect, useId, useRef } from "react";

export function TextOnPathTailwind({ text = "MOTION FOUNDRY \u2022 ", speed = 1 }) {
  const id = "tp" + useId().replace(/[^a-zA-Z0-9]/g, "");
  const tp = useRef<SVGTextPathElement>(null);
  useEffect(() => {
    let raf = 0;
    const start = performance.now();
    const tick = (now: number) => {
      tp.current?.setAttribute("startOffset", String(-((((now - start) / 1000) * 60 * speed) % 400)));
      raf = requestAnimationFrame(tick);
    };
    raf = requestAnimationFrame(tick);
    return () => cancelAnimationFrame(raf);
  }, [speed]);
  return (
    <div className="w-full text-zinc-100">
      <span className="sr-only">{text}</span>
      <svg aria-hidden viewBox="0 0 1000 320" className="h-[340px] w-full overflow-visible">
        <path id={id} d="M 0 160 C 83 50, 167 50, 250 160 S 417 270, 500 160 S 667 50, 750 160 S 917 270, 1000 160" className="fill-none stroke-zinc-700 [stroke-dasharray:2_8]" />
        <text className="fill-current text-[40px] font-extrabold uppercase tracking-wider" dominantBaseline="central">
          <textPath ref={tp} href={"#" + id}>{text.repeat(8)}</textPath>
        </text>
      </svg>
    </div>
  );
}

