"use client";

import { useEffect, useRef } from "react";

function useSmooth(ref, onFrame, lerp = 0.1) {
  useEffect(() => {
    const el = ref.current;
    let target = el.scrollTop, raf = 0;
    const emit = () => { const max = el.scrollHeight - el.clientHeight; onFrame(el.scrollTop, max > 0 ? el.scrollTop / max : 0); };
    const tick = () => {
      const d = target - el.scrollTop;
      el.scrollTop += Math.abs(d) < 0.5 ? d : d * lerp;
      emit();
      raf = Math.abs(target - el.scrollTop) < 0.5 ? 0 : requestAnimationFrame(tick);
    };
    const onWheel = (e) => {
      const max = el.scrollHeight - el.clientHeight;
      if (!raf) target = el.scrollTop;
      if ((e.deltaY < 0 && target <= 0) || (e.deltaY > 0 && target >= max)) return;
      e.preventDefault();
      target = Math.min(max, Math.max(0, target + e.deltaY));
      if (!raf) raf = requestAnimationFrame(tick);
    };
    el.addEventListener("wheel", onWheel, { passive: false });
    el.addEventListener("scroll", () => { if (!raf) emit(); }, { passive: true });
    return () => { el.removeEventListener("wheel", onWheel); cancelAnimationFrame(raf); };
  }, []);
}

export function ParallaxLayersTailwind() {
  const ref = useRef(null);
  const layers = useRef([]);
  const speeds = [0.15, 0.4, 0.7, 1.3];
  useSmooth(ref, (s) => layers.current.forEach((l, i) => { l.style.transform = `translateY(${-s * speeds[i]}px)`; }));
  return (
    <div className="relative h-[380px] w-full overflow-hidden rounded-[20px] border border-zinc-800 bg-zinc-900 text-zinc-100">
      <div ref={ref} tabIndex={0} className="h-full overflow-y-auto">
        <div aria-hidden className="pointer-events-none sticky top-0 -mb-[380px] h-[380px] overflow-hidden">
          {speeds.map((_, i) => (
            <div key={i} ref={(n) => (layers.current[i] = n)} className="absolute inset-0">
              {[0, 1, 2, 3].map((j) => (
                <span key={j} className="absolute block rounded-full bg-violet-400/30" style={{ left: `${(j * 27 + i * 13) % 90}%`, top: `${j * 220 + i * 60}px`, width: 160 - i * 36, height: 160 - i * 36 }} />
              ))}
            </div>
          ))}
        </div>
        {["Depth in motion", "Back layers crawl.", "Front layers race."].map((t) => (
          <section key={t} className="relative flex h-[380px] items-center justify-center text-5xl font-bold tracking-tight">{t}</section>
        ))}
      </div>
    </div>
  );
}

