    radial-gradient(circle at 75% 20%, color-mix(in srgb, var(--mf-hs-accent, #38bdf8) 65%, transparent), transparent 55%),
    radial-gradient(circle at 15% 90%, color-mix(in srgb, var(--mf-hs-accent, #38bdf8) 25%, #a78bfa), transparent 50%),
    linear-gradient(180deg, transparent 40%, color-mix(in srgb, var(--mf-bg, #09090b) 85%, transparent));
