"use client";

import { useEffect, useRef } from "react";

function useSmooth(ref, onFrame, lerp = 0.1) {
  useEffect(() => {
    const el = ref.current;
    let target = el.scrollTop, raf = 0;
    const emit = () => { const max = el.scrollHeight - el.clientHeight; onFrame(el.scrollTop, max > 0 ? el.scrollTop / max : 0); };
    const tick = () => {
      const d = target - el.scrollTop;
      el.scrollTop += Math.abs(d) < 0.5 ? d : d * lerp;
      emit();
      raf = Math.abs(target - el.scrollTop) < 0.5 ? 0 : requestAnimationFrame(tick);
    };
    const onWheel = (e) => {
      const max = el.scrollHeight - el.clientHeight;
      if (!raf) target = el.scrollTop;
      if ((e.deltaY < 0 && target <= 0) || (e.deltaY > 0 && target >= max)) return;
      e.preventDefault();
      target = Math.min(max, Math.max(0, target + e.deltaY));
      if (!raf) raf = requestAnimationFrame(tick);
    };
    el.addEventListener("wheel", onWheel, { passive: false });
    el.addEventListener("scroll", () => { if (!raf) emit(); }, { passive: true });
    return () => { el.removeEventListener("wheel", onWheel); cancelAnimationFrame(raf); };
  }, []);
}

export function ScrollZoomRevealTailwind() {
  const ref = useRef(null);
  const panel = useRef(null);
  const copy = useRef(null);
  useSmooth(ref, (_, p) => {
    const e = Math.min(1, p / 0.62);
    const k = 0.42 + 0.58 * e;
    panel.current.style.clipPath = `inset(${(1 - k) * 50}% round ${(1 - e) * 22}px)`;
    copy.current.style.opacity = String(Math.max(0, Math.min(1, (p - 0.5) / 0.3)));
  });
  return (
    <div className="relative h-[380px] w-full overflow-hidden rounded-[20px] border border-zinc-800 bg-zinc-900">
      <div ref={ref} tabIndex={0} className="h-full overflow-y-auto">
        <div className="h-[1216px]">
          <div className="sticky top-0 h-[380px]">
            <div ref={panel} className="absolute inset-0 bg-gradient-to-b from-violet-600 via-rose-400 to-zinc-950" style={{ clipPath: "inset(29% round 22px)" }}>
              <div ref={copy} className="flex h-full flex-col items-center pt-12 text-white opacity-0">
                <h3 className="text-5xl font-bold tracking-tight">Step into the frame</h3>
                <p className="mt-2 text-white/80">A small window grows into the whole world.</p>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

